const listRegistryConsumers = `-- name: ListRegistryConsumers :many

SELECT id, key, name, builtin, api_key_hash, webhook_url, enabled, last_used_at, created_by, created_at FROM registry_consumer ORDER BY builtin DESC, key ASC
`

// Template marketplace registry (internal/registry). Product-agnostic: these
// queries never join a Multica business table, except the few at the end
// that belong to the Multica adapter (internal/service/plugin_registry.go).
//
// Version rows carry the archive bytes; every query that does not need them
// names its columns so lists never load an archive.
func (q *Queries) ListRegistryConsumers(ctx context.Context) ([]RegistryConsumer, error) {
	rows, err := q.db.Query(ctx, listRegistryConsumers)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RegistryConsumer{}
	for rows.Next() {
		var i RegistryConsumer
		if err := rows.Scan(
			&i.ID,
			&i.Key,
			&i.Name,
			&i.Builtin,
			&i.ApiKeyHash,
			&i.WebhookUrl,
			&i.Enabled,
			&i.LastUsedAt,
			&i.CreatedBy,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

