const upsertRegistryInstallReport = `-- name: UpsertRegistryInstallReport :exec
INSERT INTO registry_install_report (consumer_id, tenant_id, listing_id, version_id, state, error)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (consumer_id, tenant_id, listing_id) DO UPDATE
SET version_id = EXCLUDED.version_id,
    state = EXCLUDED.state,
    error = EXCLUDED.error,
    reported_at = now()
`

type UpsertRegistryInstallReportParams struct {
	ConsumerID pgtype.UUID `json:"consumer_id"`
	TenantID   string      `json:"tenant_id"`
	ListingID  pgtype.UUID `json:"listing_id"`
	VersionID  pgtype.UUID `json:"version_id"`
	State      string      `json:"state"`
	Error      string      `json:"error"`
}

func (q *Queries) UpsertRegistryInstallReport(ctx context.Context, arg UpsertRegistryInstallReportParams) error {
	_, err := q.db.Exec(ctx, upsertRegistryInstallReport,
		arg.ConsumerID,
		arg.TenantID,
		arg.ListingID,
		arg.VersionID,
		arg.State,
		arg.Error,
	)
	return err
}
